import Foundation
// SHA3 four-operand group differential harness (modelled on tests/crypto).
// Expected values come from qemu-aarch64 running oracle.s (gen_cases.py).
struct Case {
    let name: String; let word: UInt32
    let rd: Int; let rn: Int; let rm: Int; let ra: Int  // ra = -1 when unused
    let vd: (UInt64, UInt64); let vn: (UInt64, UInt64)
    let vm: (UInt64, UInt64); let va: (UInt64, UInt64)
    let e: (UInt64, UInt64)
}
// Case table lives in cases.swift (generated by gen_cases.py, expected
// values merged by merge_expected.py from the qemu-aarch64 oracle run).

var passed = 0, failed = 0
for cs in cases {
    let cpu = ARM64CPU()
    cpu.platform = .vmApple
    var prog: [UInt8] = []
    for w in [cs.word, 0xD4200000 as UInt32] { for i in 0..<4 { prog.append(UInt8((w >> (8 * i)) & 0xFF)) } }
    cpu.loadProgram(prog, at: ARM64CPU.ramBase)
    cpu.fpRegisters[cs.rd * 2] = cs.vd.0; cpu.fpRegisters[cs.rd * 2 + 1] = cs.vd.1
    cpu.fpRegisters[cs.rn * 2] = cs.vn.0; cpu.fpRegisters[cs.rn * 2 + 1] = cs.vn.1
    cpu.fpRegisters[cs.rm * 2] = cs.vm.0; cpu.fpRegisters[cs.rm * 2 + 1] = cs.vm.1
    if cs.ra >= 0 { cpu.fpRegisters[cs.ra * 2] = cs.va.0; cpu.fpRegisters[cs.ra * 2 + 1] = cs.va.1 }
    do { try cpu.run(maxInstructions: 1) } catch { print("THROW \(cs.name)"); failed += 1; continue }
    let got = (cpu.fpRegisters[cs.rd * 2], cpu.fpRegisters[cs.rd * 2 + 1])
    if got == cs.e { passed += 1 } else {
        failed += 1
        print(String(format: "FAIL %@ got=%016X,%016X want=%016X,%016X", cs.name, got.0, got.1, cs.e.0, cs.e.1))
    }
}
print("sha3: \(passed) passed, \(failed) failed")
